<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\MenuItem;use Illuminate\Http\Request;
class MenuItemController extends Controller { public function index(Request $r){return MenuItem::query()->where('is_available',true)->when($r->category,fn($q,$v)=>$q->where('category',$v))->where('available_quantity','>',0)->orderBy('category')->get();} public function show(MenuItem $menuItem){return $menuItem;} public function store(Request $r){return response()->json(MenuItem::create($this->data($r)),201);} public function update(Request $r,MenuItem $menuItem){$menuItem->update($this->data($r));return $menuItem;} public function destroy(MenuItem $menuItem){$menuItem->delete();return response()->noContent();} private function data(Request $r){return $r->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:2000','category'=>'required|string|max:60','price'=>'required|numeric|min:0','available_quantity'=>'required|integer|min:0','is_available'=>'boolean','image_url'=>'nullable|url|max:2048']);} }
